import csv
import configparser
import json
import os
import re
import sys
from datetime import date, datetime, timedelta, timezone
from decimal import Decimal

WEEKDAYS = ["mon", "tue", "wed", "thu", "fri", "sat", "sun"]


def digits(text):
    return int(re.sub(r"\D", "", text) or 0)


def cents(text):
    return int((Decimal(text.strip()) * 100).to_integral_value())


def parse_offset(text):
    text = text.strip()
    sign = -1 if text.startswith("-") else 1
    hours, minutes = text.lstrip("+-").split(":")
    return sign * (int(hours) * 60 + int(minutes))


def parse_utc(text):
    return datetime.strptime(text.strip(), "%Y-%m-%dT%H:%MZ")


def parse_date(text):
    return datetime.strptime(text.strip(), "%Y-%m-%d").date()


def read_csv(path):
    with open(path, encoding="utf-8-sig", newline="") as handle:
        return list(csv.DictReader(handle))


def load_policy(path):
    parser = configparser.ConfigParser(interpolation=None)
    parser.optionxform = str
    with open(path, encoding="utf-8-sig") as handle:
        parser.read_file(handle)
    policy = {"items": {}, "cats": {}}
    stm = parser["statement"]
    policy["library"] = stm["library"].strip()
    policy["start"] = parse_date(stm["period_start"])
    policy["end"] = parse_date(stm["period_end"])
    clock = parser["clock"] if parser.has_section("clock") else {}
    policy["offset"] = parse_offset(clock.get("offset", "+00:00"))
    changes = []
    for part in clock.get("changes", "").split(";"):
        part = part.strip()
        if part:
            instant, offset = part.split()
            changes.append((parse_utc(instant), parse_offset(offset)))
    changes.sort()
    policy["changes"] = changes
    for section in parser.sections():
        kind, _, name = section.partition(":")
        values = parser[section]
        if kind == "item":
            policy["items"][name.strip().lower()] = {
                "name": name.strip(),
                "loan_days": int(values["loan_days"]),
                "renewals": int(values["renewals"]),
                "grace": int(values["grace_days"]),
                "daily": cents(values["daily"]),
                "loan_cap": cents(values["loan_cap"]),
            }
        elif kind == "category":
            cap = values["statement_cap"].strip()
            policy["cats"][name.strip().lower()] = {
                "name": name.strip(),
                "cap": None if cap.lower() == "none" else cents(cap),
                "discount": int(values["discount"]),
                "exempt": {x.strip().lower() for x in values.get("exempt", "").split(",") if x.strip()},
            }
    return policy


def local_from_instant(text, policy):
    text = text.strip()
    if text.endswith("Z") or text.endswith("z"):
        stamp = datetime.fromisoformat(text[:-1])
    else:
        stamp = datetime.fromisoformat(text)
        stamp = stamp.astimezone(timezone.utc).replace(tzinfo=None)
    offset = policy["offset"]
    for instant, value in policy["changes"]:
        if stamp >= instant:
            offset = value
    return (stamp + timedelta(minutes=offset)).strftime("%Y-%m-%d %H:%M:%S")


def load_events(directory, policy):
    events = {}
    names = sorted(os.listdir(directory))
    for name in names:
        path = os.path.join(directory, name)
        if not os.path.isfile(path):
            continue
        records = []
        if name.endswith(".csv"):
            records = read_csv(path)
            for rec in records:
                rec["_local"] = (rec.get("time") or "").strip()
        elif name.endswith(".jsonl"):
            with open(path, encoding="utf-8-sig") as handle:
                for line in handle:
                    line = line.strip()
                    if line:
                        rec = json.loads(line)
                        rec["_local"] = local_from_instant(rec["at"], policy)
