        elif ev["type"] in ("renew", "return"):
            by_loan.setdefault(loan_id, []).append(ev)

    def due_from(branch, day, item):
        return calendar.next_open(branch, day + timedelta(days=item["loan_days"]))

    loans = []
    for loan_id, co in checkouts.items():
        checkout_day = parse_date(co["_local"][:10])
        if checkout_day > end:
            continue
        item = policy["items"][co["item_type"].strip().lower()]
        branch = co["branch"].strip()
        due = due_from(branch, checkout_day, item)
        renewals = 0
        returned = None
        for ev in sorted(by_loan.get(loan_id, []), key=lambda e: e["_local"]):
            day = parse_date(ev["_local"][:10])
            if ev["type"] == "renew":
                if day <= due and renewals < item["renewals"] and day <= end:
                    renewals += 1
                    due = due_from(branch, day, item)
            else:
                returned = day
                if ev.get("via", "").strip().lower() == "dropbox":
                    returned = day - timedelta(days=1)
                break
        if returned is not None and returned < start:
            continue
        out_still = returned is None or returned > end
        end_day = end if out_still else returned
        overdue = 0
        day = due + timedelta(days=1)
        while day <= end_day:
            if calendar.is_open(branch, day):
                overdue += 1
            day += timedelta(days=1)
        if overdue < 1:
            continue
        charged = overdue if overdue > item["grace"] else 0
        num = digits(co["patron"])
        cat = category(num, checkout_day)
        base = charged * item["daily"]
        if item["name"].lower() in cat["exempt"]:
            base = 0
        base = min(base, item["loan_cap"])
        assessed = (base * (100 - cat["discount"]) * 2 + 100) // 200
        applying = [w for w in waivers if w[0] == num and w[1] in (loan_id, "*")]
        if any(w[2] is None for w in applying):
            waived = assessed
        else:
            waived = min(assessed, sum(w[2] for w in applying))
        loans.append({
            "_num": num, "loan": loan_id, "item": co.get("item", ""), "item_type": item["name"],
            "branch": branch, "checkout": checkout_day.isoformat(), "due": due.isoformat(),
            "returned": None if out_still else returned.isoformat(),
            "overdue_days": overdue, "charged_days": charged, "assessed": assessed,
            "waived": waived, "capped": 0, "billed": assessed - waived,
        })

    grouped = {}
    for loan in loans:
        grouped.setdefault(loan["_num"], []).append(loan)
    statements = []
    for num in sorted(grouped):
        rows = grouped[num]
        cat = category(num, end)
        if cat["cap"] is not None:
            excess = sum(r["billed"] for r in rows) - cat["cap"]
            if excess > 0:
                for row in sorted(rows, key=lambda r: (r["due"], r["loan"]), reverse=True):
                    take = min(excess, row["billed"])
                    row["capped"] = take
                    row["billed"] -= take
                    excess -= take
                    if excess <= 0:
                        break
        rows.sort(key=lambda r: (r["due"], r["loan"]))
        statement = {"patron": patron_names[num], "category": cat["name"], "loans": rows}
        for field in ("assessed", "waived", "capped", "billed"):
            statement[field] = sum(r[field] for r in rows)
        statements.append(statement)
        for row in rows:
            del row["_num"]

    summary = []
    for row in branches:
        bid = row["branch"].strip()
        mine = [l for st in statements for l in st["loans"] if l["branch"] == bid]
        entry = {"branch": bid, "loans": len(mine)}
        for field in ("charged_days", "assessed", "waived", "capped", "billed"):
            entry[field] = sum(l[field] for l in mine)
        summary.append(entry)

    result = {"library": policy["library"],
              "period": {"start": start.isoformat(), "end": end.isoformat()},
              "statements": statements, "branches": summary}
    with open(output, "w", encoding="utf-8") as handle:
        json.dump(result, handle, ensure_ascii=False, indent=1)


main()
